    seen=[[False]*len(g[0]) for _ in range(len(g))]; res=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]==v and not seen[r][c]:
                st=[(r,c)];seen[r][c]=True;cells=[]
                while st:
                    rr,cc=st.pop();cells.append((rr,cc))
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            nr,nc=rr+dr,cc+dc
                            if 0<=nr<len(g) and 0<=nc<len(g[0]) and g[nr][nc]==v and not seen[nr][nc]:
                                seen[nr][nc]=True;st.append((nr,nc))
                res.append(cells)
    return res
for metric in ['man','euc']:
    print('---',metric)
    for p in ['Demo pair 1','Demo pair 2']:
        ok=True
        bad=[]
        g=G[p+' input']; o=G[p+' output']
        H,W=len(g),len(g[0])
        marks=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c] not in (0,8)]
        for comp in comps_of(g,8):
            rs=min(r for r,_ in comp); cs=min(c for _,c in comp)
            ro=max(r for r,_ in comp); co=max(c for _,c in comp)
            cr,cc=(rs+ro)/2,(cs+co)/2
            ds=sorted(((abs(cr-r)+abs(cc-c) if metric=='man' else (cr-r)**2+(cc-c)**2), r,c,g[r][c]) for r,c in marks)
            # only marker cells with nonzero values count as sources
            ds=[d for d in ds if d[3]!=0]
            v=ds[-1][3]
            pred=[[o[r][c] for c in range(cs,co+1)] for r in range(rs,ro+1)]
            mism=[(pred[r][c],v) for r in range(ro-rs+1) for c in range(co-cs+1) if pred[r][c]!=v]
            if any(mism[:1]):
                ok=False; bad.append(comp)
        print(p,'ok',ok)

