def diag(P):
    # 8 dihedral transforms
    R=set()
    X=P
    def flip(X): return [row[::-1] for row in X]
    def turn(X): return [list(r) for r in zip(*X[::-1])]
    cur=X
    for k in range(4):
        R.add(cur); R.add(flip(cur))
        cur=turn(cur)
    return [list(c) for c in R]

def pats(g):
    # bbox of non-8 cells
    H,W=len(g),len(g[0])
    rs=min(r for r in range(H) for c in range(W) if g[r][c]!=8)
    cs=min(c for r in range(H) for c in range(W) if g[r][c]!=8)
    rh=max(r for r in range(H) for c in range(W) if g[r][c]!=8)-rs+1
    cw=max(c for r in range(H) for c in range(W) if g[r][c]!=8)-cs+1
    return [[g[rs+a][cs+b] for b in range(cw)] for a in range(rh)]

def solve(p, verbose=False):
    g=G[p+' input']; o=G[p+' output']
    reg=comps_of(g,8)[0]          # largest 8-component (single object)
    rb=min(r for r,_ in reg); cb=min(c for _,c in reg)
    ro=max(r for r,_ in reg); co=max(c for _,c in reg)
    P=pats(g)
    hh,ww=len(P),len(P[0])
    best=None
    for k,T in enumerate(diag(P)):
        for dr in range(-hh,ro-rb-hh+2):   # anchor such that T placed at (rb-dr,cb-dc) clips into region
            for dc in range(-ww,co-cb-ww+2):
                ok=True
                for i in range(ro-rb+1):
                    for j in range(co-cb+1):
                        v=o[i+rb][j+cb]
                        ti=i-dr; tj=j-dc
                        if 0<=ti<hh and 0<=tj<ww:
                            pred=T[ti][tj]
                            if pred!=0 and pred!=v:
                                ok=False;break
                        elif pred is None: pass
                    if not ok: break
                if ok and best is None: best=(k,dr,dc)
    return best, (hh,ww,ro-rb+1,co-cb+1)
