    H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0 and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for dr_,dc_ in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+dr_,b+dc_
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]!=0:
                            seen[x][y]=True; st.append((x,y))
                out.append(cells)
    return out

