# Rule: per row, take the LAST contiguous non-background run (rightmost run of non-bg cells), recolor everything to its right with 1. Background = most common color in the grid. Verify against all demos.
def f(g):
    from collections import Counter as C
    bg=C(x for r in g for x in r).most_common(1)[0][0]
    out=[r[:] for r in g]
    for r in g:
        last=None
        for c,x in enumerate(r):
            if x!=bg: last=c
        if last is not None and last<len(r)-1:
            for c in range(last+1,len(r)): out[r][c]=1
    return out
